-- Source: PBGC Pension Insurance Data (140454 rows)
-- Generated by gen_mart_models.py

-- DEDUP (2026-08-11 verification): 140,454 landing rows but only 140,454
-- distinct data rows across all 10 columns (incl. SOURCE_FILE) -- 9,317 exact
-- duplicates from a SINGLE load run (1 distinct run id), i.e. single-load
-- duplication, not appends. Exact dups carry no information and are collapsed.
with source as (
    select * from {{ source('ripple_raw', 'FED_PBGC_DATA') }}
    qualify row_number() over (
        partition by DATA_YEAR, PUBLICATION_DATE, PROGRAM_TYPE, TABLE_NAME,
                     METRIC_NAME, METRIC_VALUE, UNIT, STATE, SOURCE_FILE,
                     NOTES_FLAG
        order by _INGESTED_AT) = 1
)

-- DISTINCT on the cast values too: raw formatting variants ("1,000" vs
-- "1000", differing date strings) collapse only after the casts apply.
select distinct
    {{ ripple_dt('DATA_YEAR') }} as data_year,
    try_to_date(PUBLICATION_DATE) as publication_date,
    PROGRAM_TYPE as program_type,
    TABLE_NAME as table_name,
    METRIC_NAME as metric_name,
    try_to_double(METRIC_VALUE) as metric_value,
    UNIT as unit,
    STATE as state,
    SOURCE_FILE as source_file,
    NOTES_FLAG as notes_flag
from source
